files.content:
.menu {
  position: relative;
  inline-size: fit-content;
}

.menu__toggle {
  inline-size: var(--menu-toggle-size, 40px);
  border: 2px solid currentColor;
  background-color: transparent;
  background-image: url(../../../svg/menu-closed.svg);
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  cursor: pointer;
  aspect-ratio: 1 / 1;
}

.menu__toggle:hover {
  opacity: 0.6;
}

.menu__toggle_is-opened {
  background-image: url(../../../svg/menu-opened.svg);
}

.menu__list {
  position: absolute;
  inset: var(--menu-toggle-size, 40px) 0 auto auto;
  z-index: 2;
  display: none;
  inline-size: fit-content;
  block-size: fit-content;
  margin-block-start: 5px;
  border: 2px solid currentColor;
  background-color: var(--menu-background-color, #80d994);
}

.menu__toggle_is-opened ~ .menu__list {
  display: block;
}

.menu__list-item:not(:last-child) {
  border-bottom: 2px solid currentColor;
}

.menu__list-link {
  display: block;
  padding: 0.5em 1em;
  white-space: nowrap;
}

.menu__list-link:hover {
  text-decoration: none;
  background-color: var(--menu-link-hover-background-color, #fff);
}
@container (width >= 500px) {
  .menu__toggle { display: none; }
  .menu__toggle_is-opened ~ .menu__list { display: flex; }
  .menu__list {
    display: flex;
    position: static;
    border: none;
    background-color: initial;
  }
  .menu__list-item:not(:last-child) { border-bottom: none; }
  .menu__list-link { text-decoration: underline; }
  .menu__list-link:hover { text-decoration: underline; }
}

.header {
  container-type: inline-size;
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr min-content;
  padding: var(--section-padding, 20px 40px);
}

.text-content {
  padding: var(--section-padding, 20px 40px);
}

.icons {
  padding: var(--section-padding, 20px 40px);
}

.icons__text-wrapper {
  margin-block-end: 1em;
}

@media (width >= 1000px) {
  .hero-and-form {
    display: grid;
    grid-template-columns: 2fr 1fr;
  }

  .icons {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }

  .icons__text-wrapper {
    margin-block-end: 0;
  }
}

@media (width >= 1400px) {
  .icons {
    grid-template-columns: 2fr 1fr;
  }
}
